8: @main enum NotchMotionPreview {
9:     enum Failure: Error { case check(String) }
10:     /// Point-in-time diagnostic; no thread-local state is carried across an await.
11:     @MainActor static func mainThreadNow() -> Bool { Thread.isMainThread }
12:     @MainActor static func field(_ object: Any, _ name: String) -> Any? {
13:         guard let value = Mirror(reflecting: object).children.first(where: { $0.label == name })?.value else { return nil }
14:         let mirror = Mirror(reflecting: value)
15:         return mirror.displayStyle == .optional ? mirror.children.first?.value : value
16:     }
17:     @MainActor static func box(_ r: NSRect) -> [String: CGFloat] { ["x":r.minX,"y":r.minY,"width":r.width,"height":r.height] }
18:     @MainActor static func content(id: UInt32?, count: Int = 2) throws -> NotchCanvasView.Content {
19:         var tiles = [NotchTile]()
20:         if let id {
21:             let item = NotchActivity(id: "qa-motion-\(id)", kind: .download, title: "演示下载", subtitle: "演示材料.zip", symbol: "arrow.down.circle", startedAt: 0, progress: .count(count,9), isPaused: false, sessionPhase: nil)
22:             guard let cell = NotchRow.ongoingCells(from: [item]).first else { throw Failure.check("pure Core projection") }
23:             let ongoing = NotchTile.Ongoing(activityID: cell.activityID, subtitle: cell.subtitle, symbol: cell.symbol,
24:                 phase: cell.phase, isPaused: cell.isPaused, quantity: cell.quantity, quantityText: cell.quantityText,
25:                 spoken: cell.spoken, action: cell.action, closesRow: cell.closesRow, accessory: cell.accessory,
26:                 isStale: cell.isStale, isEnded: cell.isEnded)
27:             tiles.append(NotchTile(id: id, kind: .activity, snapshot: nil, icon: nil, title: cell.title, waiting: false, ongoing: ongoing))
28:         }
29:         return .init(tiles: tiles, dots: 0, dotsChanged: false, dotsY: 0, compact: nil, compactSlots: nil, alert: nil, hint: nil, notchHeight: 33.5)
30:     }
31:     @MainActor static func main() {
32:         _ = NSApplication.shared; NSApp.setActivationPolicy(.prohibited)
33:         guard Thread.isMainThread, NSApp.delegate == nil else { fatalError("own main-thread entry only") }
34:         let out = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
35:         Task { @MainActor in
36:             do { try await run(out); exit(0) }
37:             catch {
38:                 try? String(describing: error).write(to: out.appendingPathComponent("failure.txt"), atomically: true, encoding: .utf8)
39:                 print("FAILED motion probe: \(error)"); exit(1)
40:             }
41:         }
42:         // Only our entry pumps Cocoa; no product delegate, listener, controller, menu or input injection.
43:         NSApp.run()
44:     }
45:     @MainActor static func run(_ out: URL) async throws {
46:         try FileManager.default.createDirectory(at: out, withIntermediateDirectories: true)
47:         let oldOverride = Motion.reducedOverrideForProbe
48:         defer { Motion.reducedOverrideForProbe = oldOverride }
49:         var frames = [[String: Any]](), callbacks = [[String: Any]]()
50:         var counts = [String: Int]()
51:         var report: [String: Any] = ["swiftLanguageVersion":6,"productEntry":false,"realSources":0,"globalInputEvents":0,"windowActions":0,"mainThread":mainThreadNow()]
52:         func flush() throws {
53:             report["frames"] = frames; report["callbacks"] = callbacks; report["counts"] = counts
54:             try JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted,.sortedKeys]).write(to: out.appendingPathComponent("frames.json"), options: .atomic)
55:         }
56:         for reduced in [false,true] {
57:             Motion.reducedOverrideForProbe = reduced
58:             let mode = reduced ? "reduced" : "regular"
59:             let bounds = NSRect(x:0,y:0,width:800,height:400)
60:             let canvas = NotchCanvasView(frame: bounds)
61:             let window = NSWindow(contentRect: bounds, styleMask: [.borderless], backing: .buffered, defer: false)
62:             window.isReleasedWhenClosed = false; window.alphaValue = 0; window.contentView = canvas
63:             window.setFrame(NSRect(x:-8000,y:-8000,width:800,height:400),display:false)
64:             defer { window.close() }
65:             guard let island = field(canvas,"island") as? CALayer else { throw Failure.check("actual island layer") }
66:             let empty = try content(id:nil), first = try content(id:900), updated = try content(id:900,count:3), replacement = try content(id:901,count:4)
67:             let compact = NSRect(x:(800-185)/2,y:400-33.5,width:185,height:33.5)
68:             let expandedHeight = 33.5 + NotchIsland.peninsulaContentHeight(142)
69:             let expanded = NSRect(x:(800-305)/2,y:400-expandedHeight,width:305,height:expandedHeight)
70:             func token(_ shape: Motion.NotchShape) -> NotchCanvasView.Spring {
71:                 let value = Motion.notchSpring(for:shape)
72:                 return .init(response:value.response,bounce:value.bounce)
73:             }
74:             func morph(_ name: String, to rect: NSRect, content: NotchCanvasView.Content, spring: NotchCanvasView.Spring?) {
75:                 let key = mode + "-" + name
76:                 canvas.morph(to:rect,style:.init(cornerRadius:rect.height>34 ? 28:12,allCorners:false,fill:.black,border:0.5),content:content,spring:spring) {
77:                     counts[key,default:0] += 1
78:                     callbacks.append(["name":key,"mainThread":Thread.isMainThread,"time":CACurrentMediaTime()])
79:                     try? flush()
80:                 }
81:             }
82:             func snapshot(_ stage: String) throws {
83:                 guard !window.isVisible, !NSApp.isActive, Thread.isMainThread, NSApp.delegate == nil,
84:                       !NSScreen.screens.contains(where:{$0.frame.intersects(window.frame)}) else { throw Failure.check("own hidden main-thread host") }
85:                 canvas.layoutSubtreeIfNeeded()
86:                 let current = field(canvas,"current") as? NSView
87:                 var ids = [UInt32](), identities = [String](), quantities = [[String:Int]]()
88:                 func visit(_ view:NSView) {
89:                     if let tile = view as? NotchTileView, let model = field(tile,"tile") as? NotchTile {
90:                         ids.append(model.id); identities.append(String(describing:ObjectIdentifier(tile)))
91:                         if case let .count(k,n) = model.ongoing?.quantity ?? .unknown { quantities.append(["completed":k,"total":n]) }
92:                     }
93:                     view.subviews.forEach(visit)
94:                 }
95:                 if let current { visit(current) }
96:                 let name = mode + "-" + stage
97:                 guard let bitmap=canvas.bitmapImageRepForCachingDisplay(in:bounds) else {throw Failure.check("bitmap")}
98:                 canvas.cacheDisplay(in:bounds,to:bitmap)
99:                 guard let png=bitmap.representation(using:.png,properties:[:]) else {throw Failure.check("PNG")}
100:                 try png.write(to:out.appendingPathComponent(name+".png"))
101:                 let keys=island.animationKeys() ?? []
102:                 var animations=[[String:Any]]()
103:                 for key in keys { if let a=island.animation(forKey:key) { animations.append(["key":key,"duration":a.duration,"class":String(describing:type(of:a))]) } }
104:                 frames.append(["name":name,"stage":stage,"reduced":reduced,"time":CACurrentMediaTime(),"model":box(island.frame),
105:                     "presentation":island.presentation().map{box($0.frame)} as Any? ?? NSNull(),"animations":animations,
106:                     "pendingExit":field(canvas,"contentExitPending") as? Bool ?? false,"tileIDs":ids,"tileIdentities":identities,"tileQuantities":quantities,
107:                     "currentIdentity":current.map{String(describing:ObjectIdentifier($0))} as Any? ?? NSNull(),
108:                     "active":NSApp.isActive,"visible":window.isVisible,"alpha":window.alphaValue,"mainThread":Thread.isMainThread,
109:                     "cacheOnly":true])
110:                 try flush()
111:             }
112:             func wait(_ key: String) async throws {
113:                 let animationTime = (island.animationKeys() ?? []).compactMap { island.animation(forKey:$0)?.duration }.max() ?? 0
114:                 let deadline=ProcessInfo.processInfo.systemUptime+max(4,animationTime+1)
115:                 while counts[mode+"-"+key,default:0]==0, ProcessInfo.processInfo.systemUptime<deadline {try await Task.sleep(nanoseconds:10_000_000)}
116:                 guard counts[mode+"-"+key,default:0]==1 else {throw Failure.check("completion \(mode)-\(key)")}
117:                 try await Task.sleep(nanoseconds:180_000_000)
118:             }
119:             morph("initial",to:compact,content:empty,spring:nil); try await wait("initial"); try snapshot("initial")
120:             morph("open",to:expanded,content:first,spring:token(.expanded)); try snapshot("open-start"); try await wait("open"); canvas.settle(); try snapshot("open-settled")
121:             morph("same-id",to:expanded,content:updated,spring:token(.expanded)); try await wait("same-id"); canvas.settle(); try snapshot("same-id")
122:             morph("replace-id",to:expanded,content:replacement,spring:token(.expanded)); try await wait("replace-id"); canvas.settle(); try snapshot("replace-id")
123:             morph("close-interrupted",to:compact,content:empty,spring:token(.compact)); try snapshot("close-before-interrupt")
124:             try await Task.sleep(nanoseconds:10_000_000)
125:             morph("reopen",to:expanded,content:replacement,spring:token(.expanded)); try await wait("reopen"); canvas.settle()
126:             try await Task.sleep(nanoseconds:200_000_000); try snapshot("reopened")
127:             morph("close-final",to:compact,content:empty,spring:token(.compact)); try await wait("close-final"); canvas.settle(); try snapshot("closed")
128:             window.close()
129:         }
130:         report["overrideRestoredTo"] = oldOverride as Any? ?? NSNull()
131:         report["status"] = "completed_callbacks_static_cache_only"
132:         try flush(); print("PASS \(frames.count) actual Swift6 motion/cancellation snapshots; callbacks main-thread; visual compositor untested")
133:     }
134: }
